// Package emit renders mock source files.
//
// Each interface becomes a concrete moq-style mock: the type text of its methods is copied with
// re-qualified imports, and every call is recorded under a mutex.
package emit

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"

	"github.com/sivchari/mimic/internal/iface"
	"github.com/sivchari/mimic/internal/load"
	"github.com/sivchari/mimic/internal/rewrite"
)

// tool is the name written into generated files and messages.
const tool = "mimic"

// sourcePrefix starts the header line that records the interface a mock was generated from.
const sourcePrefix = "// source: "

// Options configures Generate.
type Options struct {
	Package string // package clause of the generated file
	OutPath string // import path of the output package; "" if unknown
	// SkipEnsure leaves out the compile-time check that each mock implements its interface. The
	// interface's package is then imported only if a method signature names one of its types,
	// which lets a mock live in a package that the interface's package imports.
	SkipEnsure bool
}

// Generate renders one file containing a mock for each interface.
//
// Every package-level name the file declares is derived from an interface name (RepoMock,
// RepoMockGetCall), so files generated by separate runs
// for different interfaces can be compiled in one package.
func Generate(l *load.Loader, opts Options, its []*iface.Interface) (src []byte, err error) {
	defer load.Recover(&err)

	w := rewrite.NewWriter(l, opts.OutPath)
	nm := newNamer(l, w)

	mocks := make([]*mock, 0, len(its))
	names := map[string]string{}

	for _, it := range its {
		m, err := prepare(nm, it)
		if err != nil {
			return nil, fmt.Errorf("%s.%s: %w", it.PkgName, it.Name, err)
		}

		if prev, dup := names[m.mt]; dup {
			return nil, fmt.Errorf("%s.%s and %s would both be generated as %s", it.PkgName, it.Name, prev, m.mt)
		}

		names[m.mt] = it.PkgName + "." + it.Name

		mocks = append(mocks, m)
	}

	// The interface's package is registered after every method signature so that it never takes a
	// name away from a package the signatures use; moq orders its imports the same way.
	if !opts.SkipEnsure {
		for _, m := range mocks {
			m.qualify()
		}
	}

	var body bytes.Buffer

	for _, m := range mocks {
		m.emit(&body, opts.SkipEnsure)
	}

	w.Imports.Use("sync")

	var b bytes.Buffer

	fmt.Fprintf(&b, "// Code generated by %s. DO NOT EDIT.\n", tool)

	for _, it := range its {
		fmt.Fprintf(&b, "%s%s.%s\n", sourcePrefix, it.Path, it.Name)
	}

	fmt.Fprintf(&b, "\npackage %s\n\nimport (\n%s)\n\n", opts.Package, w.Imports.Lines())
	b.Write(body.Bytes())

	out, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format generated source: %w", err)
	}

	return out, nil
}

// mock is the plan for the mock of one interface.
type mock struct {
	w  *rewrite.Writer
	it *iface.Interface

	mt     string   // mock type name
	ifDecl []string // declarations of the interface's type parameters
	args   []string // names of the interface's type parameters
	tdecl  string   // "[T any, U comparable]" or ""
	targs  string   // "[T, U]" or ""
	inst   string   // mock type with its type arguments
	ifq    string   // qualified interface name without type arguments; "" if unchecked
	ifInst string   // qualified interface name with its type arguments; "" if unchecked
}

// prepare writes the types of the interface for the output package and plans the mock.
func prepare(nm *namer, it *iface.Interface) (m *mock, err error) {
	defer load.Recover(&err)

	w := nm.w

	for _, im := range it.Methods {
		if !im.Exported() && !w.IsSelf(im.Pkg) {
			return nil, fmt.Errorf("unexported method %s cannot be implemented outside its package", im.Name)
		}
	}

	m = &mock{w: w, it: it, mt: it.Name + "Mock"}

	for _, t := range it.TParams {
		if w.Imports.Taken(t.Name) {
			return nil, fmt.Errorf("type parameter %s clashes with an import name", t.Name)
		}

		m.ifDecl = append(m.ifDecl, t.Name+" "+w.Type(t.Constraint, it.Ctx))
		m.args = append(m.args, t.Name)
	}

	for _, im := range it.Methods {
		nm.fill(im, m.reserved(im))
	}

	m.tdecl, m.targs = brk(m.ifDecl), brk(m.args)
	m.inst = m.mt + m.targs

	return m, nil
}

// qualify names the interface for the conformance check. It marks the interface's package as
// imported, so it must not run when the check is skipped.
func (m *mock) qualify() {
	m.ifq = m.w.Qualify(m.it.Path, m.it.PkgName) + m.it.Name
	m.ifInst = m.ifq + m.targs
}

// reserved returns the identifiers that the body of a method of im uses, which a variable of
// the method must not shadow.
func (m *mock) reserved(im *iface.Method) map[string]bool {
	r := map[string]bool{"mock": true, "callInfo": true, "panic": true, "append": true, m.mt + im.Name + "Call": true}

	for _, a := range m.args {
		r[a] = true
	}

	return r
}

// brk renders a type parameter or argument list, or "" if it is empty.
func brk(s []string) string {
	if len(s) == 0 {
		return ""
	}

	return "[" + strings.Join(s, ", ") + "]"
}

// printer appends formatted text to a buffer.
type printer struct {
	b *bytes.Buffer
}

func (p printer) printf(format string, args ...any) {
	fmt.Fprintf(p.b, format, args...)
}

func (m *mock) emit(buf *bytes.Buffer, skipEnsure bool) {
	p := printer{buf}

	if !skipEnsure {
		m.emitCheck(p)
	}

	m.emitType(p)

	for _, im := range m.it.Methods {
		m.emitMethod(p, im)
	}
}

// callType returns the name of the call record type of method im.
func (m *mock) callType(im *iface.Method) string {
	return m.mt + im.Name + "Call" + m.targs
}

// emitCheck writes the compile-time conformance check. It fails to compile when the interface
// changed and the mock was not regenerated.
func (m *mock) emitCheck(p printer) {
	p.printf("// If this fails to compile, %s.%s has changed: run %q.\n", m.it.PkgName, m.it.Name, tool+" gen")

	if len(m.ifDecl) == 0 {
		p.printf("var _ %s = (*%s)(nil)\n\n", m.ifq, m.mt)

		return
	}

	p.printf("func _%s() { var _ %s = (*%s)(nil) }\n\n", m.tdecl, m.ifInst, m.inst)
}

func (m *mock) emitType(p printer) {
	p.printf("// %s is a mock of %s.%s.\n", m.mt, m.it.PkgName, m.it.Name)

	p.printf("type %s%s struct {\n", m.mt, m.tdecl)

	for _, im := range m.it.Methods {
		ps := make([]string, len(im.Params))

		for i := range im.Params {
			ps[i] = im.Params[i].Var + " " + ptype(im, i)
		}

		p.printf("\t%sFunc func(%s)%s\n", im.Name, strings.Join(ps, ", "), resultList(im))
	}

	p.printf("\n\tmu sync.Mutex\n")

	for _, im := range m.it.Methods {
		p.printf("\tcalls%s []%s\n", im.Name, m.callType(im))
	}

	p.printf("}\n\n")
}

func (m *mock) emitMethod(p printer, im *iface.Method) {
	ct := m.callType(im)

	// An alias of an anonymous struct keeps the record assignable to, and inferable as, the struct
	// type that moq-generated code uses, which a defined type would not.
	p.printf("// %s%sCall is one call of %s.%s.\ntype %s%sCall%s = struct {\n", m.mt, im.Name, m.it.Name, im.Name, m.mt, im.Name, m.tdecl)

	for i := range im.Params {
		p.printf("\t%s %s\n", im.Params[i].Field, ftype(im, i))
	}

	p.printf("}\n\n")

	ps := make([]string, len(im.Params))
	lits := make([]string, len(im.Params))
	call := make([]string, len(im.Params))

	for i := range im.Params {
		v := im.Params[i].Var

		ps[i] = v + " " + ptype(im, i)
		lits[i] = im.Params[i].Field + ": " + v

		call[i] = v
		if im.Variadic && i == len(im.Params)-1 {
			call[i] += "..."
		}
	}

	ret := ""
	if len(im.Results) > 0 {
		ret = "return "
	}

	p.printf("func (mock *%s) %s(%s)%s {\n", m.inst, im.Name, strings.Join(ps, ", "), resultList(im))
	p.printf("\tif mock.%sFunc == nil {\n\t\tpanic(\"%s: %s.%s called, but %sFunc is nil\")\n\t}\n", im.Name, tool, m.mt, im.Name, im.Name)
	p.printf("\tcallInfo := %s{%s}\n", ct, strings.Join(lits, ", "))
	p.printf("\tmock.mu.Lock()\n\tmock.calls%s = append(mock.calls%s, callInfo)\n\tmock.mu.Unlock()\n", im.Name, im.Name)
	p.printf("\t%smock.%sFunc(%s)\n}\n\n", ret, im.Name, strings.Join(call, ", "))

	p.printf("// %sCalls returns the calls made to %s so far.\n", im.Name, im.Name)
	p.printf("func (mock *%s) %sCalls() []%s {\n\tmock.mu.Lock()\n\tcalls := append([]%s(nil), mock.calls%s...)\n\tmock.mu.Unlock()\n\n\treturn calls\n}\n\n", m.inst, im.Name, ct, ct, im.Name)
}

func resultList(im *iface.Method) string {
	switch len(im.Results) {
	case 0:
		return ""
	case 1:
		return " " + im.Results[0].Out
	}

	rs := make([]string, len(im.Results))
	for i, r := range im.Results {
		rs[i] = r.Out
	}

	return " (" + strings.Join(rs, ", ") + ")"
}

// ptype is the type of parameter i as written in a signature.
func ptype(im *iface.Method, i int) string {
	if im.Variadic && i == len(im.Params)-1 {
		return "..." + im.Params[i].Out
	}

	return im.Params[i].Out
}

// ftype is the type of parameter i as stored in a call record.
func ftype(im *iface.Method, i int) string {
	if im.Variadic && i == len(im.Params)-1 {
		return "[]" + im.Params[i].Out
	}

	return im.Params[i].Out
}
